// ============================================
// GOOGLE TRENDS FETCH — v10 COOKING NICHE
// Fetches trending cooking topics from last 7 days
// Uses Google Trends RSS (no API key needed)
// Category-aware with round-robin rotation
// ============================================

const CATEGORY_ORDER = [1,39,40,41,42,43,44,45,46,47];
const staticData = $getWorkflowStaticData('global');

// STEP 1: Round-robin category rotation
let rotIdx = -1;
try { rotIdx = parseInt(staticData['categoryRotationIndex'] || '-1'); } catch(e) { rotIdx = -1; }
if (rotIdx === -1) {
  const now = new Date();
  rotIdx = (now.getMinutes() + now.getHours()) % CATEGORY_ORDER.length;
} else {
  rotIdx = (rotIdx + 1) % CATEGORY_ORDER.length;
}
staticData['categoryRotationIndex'] = String(rotIdx);
const currentCategoryId = CATEGORY_ORDER[rotIdx];

// STEP 2: Category-to-search-terms mapping
const CATEGORY_SEARCH_TERMS = {
  1:  ['quick easy recipes', 'fast dinner ideas', 'easy weeknight meals', '15 minute meals', 'simple recipes'],
  39: ['breakfast recipes', 'brunch ideas', 'easy breakfast', 'morning meal ideas', 'pancake recipes'],
  40: ['lunch recipes', 'easy lunch ideas', 'sandwich recipes', 'lunch meal prep', 'quick lunch'],
  41: ['dinner recipes', 'easy dinner ideas', 'family dinner', 'weeknight dinner', 'supper ideas'],
  42: ['healthy recipes', 'low calorie meals', 'nutritious food', 'clean eating recipes', 'diet recipes'],
  43: ['vegetarian recipes', 'vegan meals', 'meatless dinner', 'plant based recipes', 'veggie dishes'],
  44: ['dessert recipes', 'cake recipes', 'cookie recipes', 'baking ideas', 'sweet treats'],
  45: ['snack recipes', 'appetizer ideas', 'party food', 'finger foods', 'easy snacks'],
  46: ['drink recipes', 'cocktail recipes', 'smoothie recipes', 'mocktail ideas', 'beverage recipes'],
  47: ['cooking tips', 'kitchen hacks', 'cooking techniques', 'chef tips', 'food science cooking']
};

const CATEGORY_NAMES = {
  1: 'Quick & Easy Recipes', 39: 'Breakfast Recipes', 40: 'Lunch Ideas',
  41: 'Dinner Recipes', 42: 'Healthy Recipes', 43: 'Vegetarian Recipes',
  44: 'Desserts & Sweets', 45: 'Snacks & Appetizers',
  46: 'Beverages & Drinks', 47: 'Cooking Tips & Guides'
};

// STEP 3: Large evergreen fallback pool (used only if all other methods fail)
const FALLBACK_POOL = {
  1:  ['15-Minute Lemon Garlic Butter Shrimp Pasta','One-Pan Honey Mustard Chicken and Vegetables','Quick Black Bean Tacos with Avocado Crema','20-Minute Teriyaki Salmon Rice Bowl','Easy Caprese Pasta with Fresh Basil','Speedy Turkey and Veggie Fried Rice'],
  39: ['Classic Fluffy Buttermilk Pancakes from Scratch','Savory Shakshuka with Feta and Fresh Herbs','Overnight French Toast Casserole with Berries','Crispy Hash Brown Breakfast Skillet','Banana Oat Protein Smoothie Bowl','Veggie Frittata with Sun-Dried Tomatoes'],
  40: ['Banh Mi Sandwich with Pickled Vegetables','Buffalo Chicken Lettuce Wraps with Blue Cheese','Mediterranean Quinoa Salad Bowl','Roasted Tomato Basil Soup with Crusty Bread','Classic Club Sandwich with Homemade Mayo','Asian Sesame Noodle Cold Salad'],
  41: ['Red Wine Braised Short Ribs with Mashed Potatoes','Classic Chicken Piccata with Capers and Lemon','Slow Cooker Pork Carnitas Tacos','Thai Green Curry with Jasmine Rice','One-Pot Creamy Tuscan Chicken Pasta','Garlic Butter Salmon with Asparagus'],
  42: ['Zucchini Noodles with Avocado Pesto','Baked Lemon Herb Salmon with Quinoa','Turkey Lettuce Wrap Bowls with Sriracha','Roasted Cauliflower and Chickpea Buddha Bowl','Greek Salad with Grilled Chicken','Lentil Vegetable Soup with Turmeric'],
  43: ['Sweet Potato Black Bean Enchiladas','Mushroom Lentil Shepherd Pie','Crispy Tofu Teriyaki Bowl','Vegetarian Chili with Three Beans','Eggplant Parmesan with Homemade Marinara','Spinach Ricotta Stuffed Pasta Shells'],
  44: ['Classic New York Cheesecake with Berry Sauce','Dark Chocolate Lava Cakes','Homemade Apple Cinnamon Crumble','Classic Tiramisu with Espresso','Salted Caramel Brownies','Lemon Meringue Tart with Shortcrust Pastry'],
  45: ['Crispy Baked Buffalo Cauliflower Wings','Homemade Soft Pretzels with Cheese Dip','Loaded Avocado Toast Variations','Spinach Artichoke Dip with Pita Chips','Honey Garlic Chicken Skewers','Mini Caprese Skewers with Balsamic Glaze'],
  46: ['Homemade Strawberry Basil Lemonade','Classic Espresso Martini Recipe','Turmeric Golden Milk Latte','Sparkling Hibiscus Iced Tea','Mango Coconut Smoothie Bowl','Classic Old Fashioned Whiskey Cocktail'],
  47: ['How to Season and Care for Cast Iron Skillets','Mastering Knife Skills for Faster Meal Prep','The Science Behind Perfect Caramelization','How to Make Your Own Stock from Scratch','Understanding Flavor Profiles and Seasoning','Food Pairing Principles for Better Cooking']
};

// STEP 4: Fetch Google Trends RSS for cooking-related topics (last 7 days)
const searchTerms = CATEGORY_SEARCH_TERMS[currentCategoryId] || CATEGORY_SEARCH_TERMS[1];
let googleTrendsTopics = [];

// Google Trends daily trends RSS (US, food category)
const trendsUrls = [
  'https://trends.google.com/trends/trendingsearches/daily/rss?geo=US',
  'https://trends.google.com/trends/trendingsearches/realtime/rss?geo=US&category=f' // food category
];

for (const url of trendsUrls) {
  try {
    const resp = await $http.get(url, {
      timeout: 12000,
      headers: { 'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36' }
    });
    const body = typeof resp === 'string' ? resp : (resp.data || resp.body || '');
    if (!body) continue;

    // Parse RSS items
    const items = body.match(/<item>([\s\S]*?)<\/item>/g) || [];
    for (const item of items) {
      const titleMatch = item.match(/<title>(?:<!\[CDATA\[)?([^\]<]+)(?:\]\]>)?<\/title>/);
      const title = titleMatch ? titleMatch[1].trim() : '';
      if (title.length > 5) googleTrendsTopics.push(title);
    }
  } catch(e) { /* silent fail, will use Gemini Trends API next */ }
}

// STEP 5: Also try SerpAPI Google Trends (if available, otherwise skip)
// We'll use Gemini to generate trending-inspired unique topics

// STEP 6: Get existing WP posts to avoid duplicates
const wpBase = $('Build Config').first().json._wpBase;
const auth = $('Build Config').first().json._auth;
let wpTitlesAll = [];
let wpSlugsAll = [];
try {
  const wpResp = await $http.get(`${wpBase}/wp-json/wp/v2/posts?per_page=100&_fields=title,slug`, {
    headers: { 'Authorization': auth }, timeout: 15000
  });
  const posts = wpResp.data || [];
  wpTitlesAll = posts.map(p => (p.title?.rendered || '').toLowerCase().trim());
  wpSlugsAll = posts.map(p => (p.slug || '').toLowerCase().trim());
} catch(e) { /* continue without WP data */ }

// STEP 7: Get local used topics memory
if (!staticData.usedTopics) staticData.usedTopics = [];
const localBlacklist = staticData.usedTopics.map(t => t.toLowerCase().trim());

// STEP 8: Duplicate check function
function isDuplicate(title) {
  const t = title.toLowerCase().trim();
  const s = title.toLowerCase().replace(/[^a-z0-9]+/g, '-').trim();
  const isWpDupe = wpTitlesAll.some(et => et === t || et.includes(t.substring(0,30))) ||
                   wpSlugsAll.some(es => es === s || es.includes(s.substring(0,30)));
  const isLocalDupe = localBlacklist.some(lt => lt === t || t.includes(lt.substring(0,25)));
  return isWpDupe || isLocalDupe;
}

// STEP 9: Filter Google Trends to find cooking-relevant, non-duplicate topics
const cookingKeywords = ['recipe', 'food', 'cook', 'meal', 'dish', 'chicken', 'beef', 'pasta',
  'salad', 'soup', 'bake', 'grill', 'fry', 'breakfast', 'dinner', 'lunch', 'snack',
  'dessert', 'cake', 'cookie', 'sauce', 'vegetarian', 'vegan', 'healthy', 'diet',
  'smoothie', 'drink', 'cocktail', 'pizza', 'burger', 'taco', 'rice', 'bread'];

const trendingCookingTopics = googleTrendsTopics.filter(topic => {
  const lower = topic.toLowerCase();
  const isCooking = cookingKeywords.some(kw => lower.includes(kw));
  return isCooking && !isDuplicate(topic) && topic.length > 8;
});

// STEP 10: Select best topic
let selectedTopic = null;
let topicSource = 'fallback';

if (trendingCookingTopics.length > 0) {
  selectedTopic = trendingCookingTopics[Math.floor(Math.random() * trendingCookingTopics.length)];
  topicSource = 'google_trends';
} else {
  // Use Gemini to generate a fresh trending-inspired topic for this category
  const catName = CATEGORY_NAMES[currentCategoryId];
  const randomSearchTerm = searchTerms[Math.floor(Math.random() * searchTerms.length)];

  // Use fallback pool
  const pool = FALLBACK_POOL[currentCategoryId] || FALLBACK_POOL[1];
  const freshPool = pool.filter(f => !isDuplicate(f));

  if (freshPool.length > 0) {
    selectedTopic = freshPool[Math.floor(Math.random() * freshPool.length)];
    topicSource = 'evergreen_pool';
  } else {
    // Last resort: generate unique topic name from category
    const catName = CATEGORY_NAMES[currentCategoryId];
    selectedTopic = `The Ultimate Guide to ${catName} for Home Cooks`;
    topicSource = 'generated';
  }
}

// STEP 11: Update memory (keep last 100 topics)
staticData.usedTopics.push(selectedTopic);
if (staticData.usedTopics.length > 100) staticData.usedTopics.shift();

return [{ json: {
  trendingTopic: selectedTopic,
  context: `Trending cooking topic related to ${CATEGORY_NAMES[currentCategoryId]}`,
  sourceUrl: '',
  topicSource: topicSource,
  _currentCategoryId: currentCategoryId,
  _forcedCategoryId: currentCategoryId,
  _forcedCategoryName: CATEGORY_NAMES[currentCategoryId],
  _rotationIndex: rotIdx,
  _trendsFound: googleTrendsTopics.length,
  _cookingTrendsFound: trendingCookingTopics.length
} }];

// Merge config + topic data into single context object
const configData = $('Build Config').first().json;
const topicData = $input.first().json;

return [{ json: {
  ...configData,
  ...topicData
} }];

// Check if Mistral succeeded, if not prepare for Gemini fallback
const mistralResp = $input.first().json;
const prevData = $('Prepare AI Prompt').first().json;

const hasContent = mistralResp.choices && 
                   mistralResp.choices[0] && 
                   mistralResp.choices[0].message && 
                   mistralResp.choices[0].message.content &&
                   mistralResp.choices[0].message.content.length > 200;

if (hasContent) {
  return [{ json: { ...prevData, _aiRawOutput: mistralResp.choices[0].message.content, _aiSource: 'mistral' } }];
} else {
  // Signal to try Gemini
  return [{ json: { ...prevData, _mistralFailed: true, _aiSource: 'pending_gemini' } }];
}

// Normalize Gemini output to same format as Mistral
const geminiResp = $input.first().json;
const prevData = $('Prepare AI Prompt').first().json;

const text = geminiResp.candidates?.[0]?.content?.parts?.[0]?.text || '';

if (text.length > 200) {
  return [{ json: { ...prevData, _aiRawOutput: text, _aiSource: 'gemini' } }];
} else {
  return [{ json: { ...prevData, _aiRawOutput: '', _aiSource: 'gemini_failed', _allAiFailed: true } }];
}

// Merge Mistral success OR Gemini output into one stream
// This node receives data from either Check Mistral Output (success path) or Normalize Gemini Output
return $input.all();

// ============================================
// EXTRACT & PARSE ARTICLE — v11 FORMATTED
// Handles Table conversion, List wrapping, and Styled callouts
// ============================================

const createCleanSlug = (text) => {
  if (!text) return 'cooking-recipe';
  return text.toLowerCase()
    .replace(/[^a-z0-9\s-]/g, '')
    .replace(/\s+/g, '-')
    .replace(/-+/g, '-')
    .replace(/^-|-$/g, '')
    .substring(0, 60)
    .replace(/-$/, '');
};

const d = $input.first().json;
const raw = d._aiRawOutput || '';
const forcedCatId = d._forcedCategoryId || 1;
const forcedCatName = d._forcedCategoryName || 'Quick & Easy Recipes';
const topicFallback = d.trendingTopic || 'Easy Cooking Recipes';

// Emergency fallback if AI completely failed
if (!raw || raw.length < 200) {
  return [{ json: {
    ...d,
    title: `The Complete Guide to ${topicFallback}`,
    articleHTML: `<p>Discover our expert guide to ${topicFallback} with professional tips and techniques.</p><h2>Getting Started</h2><p>This comprehensive guide covers everything you need to know about ${topicFallback}.</p>`,
    category_id: forcedCatId,
    slug: createCleanSlug(topicFallback),
    _hasContent: false
  } }];
}

// Parse the output
const lines = raw.split('\n');
let title='', slug='', metaDesc='', tagsRaw='', excerpt='';
let imgQ1='', imgQ2='', imgQ3='', imgQ4='';
let articleStart = -1;

for (let i = 0; i < lines.length; i++) {
  const t = lines[i].trim();
  if (t.startsWith('TITLE:'))    title    = t.slice(6).trim().replace(/^[\"']|[\"']$/g, '');
  if (t.startsWith('SLUG:'))     slug     = createCleanSlug(t.slice(5).trim());
  if (t.startsWith('META:'))     metaDesc = t.slice(5).trim().substring(0, 155);
  if (t.startsWith('TAGS:'))     tagsRaw  = t.slice(5).trim();
  if (t.startsWith('EXCERPT:'))  excerpt  = t.slice(8).trim();
  if (t.startsWith('QUERY1:'))   imgQ1    = t.slice(7).trim();
  if (t.startsWith('QUERY2:'))   imgQ2    = t.slice(7).trim();
  if (t.startsWith('QUERY3:'))   imgQ3    = t.slice(7).trim();
  if (t.startsWith('QUERY4:'))   imgQ4    = t.slice(7).trim();
  if (t.includes('===START===')) { articleStart = i + 1; break; }
}

let articleHTML = '';
if (articleStart >= 0) {
  const rest = lines.slice(articleStart);
  const endIdx = rest.findIndex(l => l.includes('===END==='));
  articleHTML = (endIdx >= 0 ? rest.slice(0, endIdx) : rest).join('\n').trim();
} else {
  const firstH = raw.indexOf('<p>');
  if (firstH >= 0) articleHTML = raw.substring(firstH);
  else articleHTML = raw;
}

// FORMATTING IMPROVEMENTS
// 1. Convert Markdown Tables to HTML
const convertTables = (html) => {
    const lines = html.split('\n');
    let newLines = [];
    let tableData = [];
    let inTable = false;

    const flushTable = () => {
        if (tableData.length === 0) return '';
        let t = '<div style=\"overflow-x:auto;margin:24px 0;\"><table style=\"width:100%;border-collapse:collapse;border:1px solid #eee;font-size:14px;\">';
        const data = tableData.filter(row => !row.every(cell => cell.match(/^[ :\-\|]+$/)));
        data.forEach((row, i) => {
            const tag = i === 0 ? 'th' : 'td';
            const style = i === 0 ? 'background:#fdf2f0;color:#c0392b;padding:12px;border:1px solid #eee;text-align:left;' : 'padding:12px;border:1px solid #eee;';
            t += '<tr>';
            row.forEach(cell => { t += `<${tag} style=\"${style}\">${cell.trim()}</${tag}>`; });
            t += '</tr>';
        });
        t += '</table></div>';
        tableData = [];
        return t;
    };

    for (let i = 0; i < lines.length; i++) {
        const line = lines[i].trim();
        if (line.startsWith('|') && line.endsWith('|')) {
            inTable = true;
            tableData.push(line.split('|').slice(1, -1));
        } else {
            if (inTable) { newLines.push(flushTable()); inTable = false; }
            newLines.push(lines[i]);
        }
    }
    if (inTable) newLines.push(flushTable());
    return newLines.join('\n');
};

articleHTML = convertTables(articleHTML);

// 2. Wrap loose <li> tags and handle markdown lists
articleHTML = articleHTML
  .replace(/^(?!<li|<ul|<ol)\s*[\*\-]\s+(.+)$/gm, '<li>$1</li>') // Convert * or - to <li>
  .replace(/(<li>[\s\S]*?<\/li>)/g, (match) => {
      // This is a simple list wrapper - group adjacent <li> tags
      return match; 
  });
// More robust wrapping
const wrapLists = (html) => {
    return html.replace(/(<li>[\s\S]*?<\/li>\n?)+/g, (match) => {
        if (match.trim().startsWith('<ul') || match.trim().startsWith('<ol')) return match;
        return `<ul>\n${match.trim()}\n</ul>\n`;
    });
};
articleHTML = wrapLists(articleHTML);

// 3. Style Callouts (Pro Tips, Chef Tips, etc.)
articleHTML = articleHTML.replace(/<p>(<strong>)?(Pro Tip|Chef Tip|Science Behind the Magic|Nutrition Facts|Note):?\s*(<\/strong>)?([\s\S]*?)<\/p>/gi, (match, s1, type, s2, content) => {
    return `<div style=\"background:#f9f9f9;border-left:4px solid #c0392b;padding:16px 20px;margin:24px 0;border-radius:0 8px 8px 0;\"><strong>${type}:</strong>${content}</div>`;
});

// 4. General Cleanup
articleHTML = articleHTML
  .replace(/^#{3}\s+(.+)$/gm, '<h3>$1</h3>')
  .replace(/^#{2}\s+(.+)$/gm, '<h2>$1</h2>')
  .replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>')
  .replace(/__(.*?)__/g, '<strong>$1</strong>')
  .replace(/\u2014/g, '-')
  .replace(/^---\s*$/gm, '<hr style=\"border:0;border-top:1px solid #eee;margin:32px 0;\"/>');

let tags = tagsRaw.split(',').map(t => t.replace(/[\\\[\\\]\"']/g,'').trim()).filter(t => t.length > 1).slice(0,6);

return [{ json: {
  ...d,
  title: title || topicFallback,
  articleHTML,
  category_id: forcedCatId,
  slug: slug || createCleanSlug(title),
  imgQuery1: imgQ1 || topicFallback,
  imgQuery4: imgQ4 || 'cooking chef'
} }];

// ============================================
// ENHANCE ARTICLE — v10 DEDUP IMAGES + TOC
// Strict image deduplication by photo ID
// Smart injection at H2 positions 2, 4, 6
// ============================================
const d = $('Extract & Parse Article').first().json;
const articleTopic = d.trendingTopic || d.title || 'cooking';

// Track used photo IDs to prevent duplicate images
const usedImgIds = new Set();

const normalizeUrl = (u) => {
  if (!u) return '';
  return u.split('?')[0] + '?auto=compress&cs=tinysrgb&fit=crop&h=630&w=1200';
};

function pickBestImage(nodeName, queryHint) {
  try {
    const apiResponse = $(nodeName).first().json;
    const photos = (apiResponse?.photos) || [];
    if (photos.length === 0) return null;

    // Filter out already-used photo IDs
    const available = photos.filter(p => !usedImgIds.has(p.id));
    if (available.length === 0) return null;

    // Score by keyword relevance
    const keywords = (queryHint || articleTopic).toLowerCase()
      .replace(/[^a-z0-9 ]/g, ' ').split(/\s+/).filter(w => w.length > 2);

    const scored = available.map(p => {
      const text = ((p.alt || '') + ' ' + (p.url || '') + ' ' + (p.photographer || '')).toLowerCase();
      let score = 0;
      for (const kw of keywords) { if (text.includes(kw)) score++; }
      // Prefer larger images
      if (p.width >= 1200 && p.height >= 630) score += 2;
      return { photo: p, score };
    });

    scored.sort((a, b) => b.score - a.score);
    const pick = scored[0].photo;

    // Mark this photo ID as used
    usedImgIds.add(pick.id);

    return {
      url: normalizeUrl(pick.src?.original || pick.src?.large2x || pick.src?.large),
      alt: pick.alt || articleTopic,
      pName: pick.photographer || 'Pexels',
      pUrl: pick.photographer_url || 'https://www.pexels.com',
      pgUrl: pick.url || 'https://www.pexels.com',
      id: pick.id
    };
  } catch(e) { return null; }
}

let html = d.articleHTML || '';
const h2Matches = html.match(/<h2[^>]*>[\s\S]*?<\/h2>/gi) || [];

// Pick images for positions 2, 5, 8, 11
const img1 = pickBestImage('Fetch Inline Image 1 (Pexels)', h2Matches[1]?.replace(/<[^>]*>/g,'') || articleTopic);
const img2 = pickBestImage('Fetch Inline Image 2 (Pexels)', h2Matches[4]?.replace(/<[^>]*>/g,'') || articleTopic);
const img3 = pickBestImage('Fetch Inline Image 3 (Pexels)', h2Matches[7]?.replace(/<[^>]*>/g,'') || articleTopic);
const img4 = pickBestImage('Fetch Inline Image 4 (Pexels)', h2Matches[10]?.replace(/<[^>]*>/g,'') || articleTopic);

function makeImgBlock(img, altHint) {
  if (!img || !img.url) return '';
  const alt = ((altHint || img.alt || articleTopic) + ' - texasdadcooks.com')
    .replace(/"/g, "'").substring(0, 120);
  return `\n<figure style="margin:28px 0 36px;text-align:center;">\n<img src="${img.url}" alt="${alt}" width="1200" height="630" style="width:100%;max-width:800px;height:auto;border-radius:10px;display:block;margin:0 auto;" loading="lazy"/>\n<figcaption style="font-size:11px;color:#888;text-align:center;margin-top:6px;font-style:italic;">Photo by <a href="${img.pUrl}" target="_blank" rel="noopener noreferrer">${img.pName}</a> on <a href="${img.pgUrl}" target="_blank" rel="noopener noreferrer">Pexels</a></figcaption>\n</figure>\n`;
}

// Inject images after H2 positions 2, 5, 8, 11
let h2Count = 0;
const enhancedBody = html.replace(/<h2([^>]*)>([\s\S]*?)<\/h2>/gi, (match, attrs, content) => {
  h2Count++;
  const id = attrs.includes('id=') ? '' : ` id="section-${h2Count}"`;
  const tagWithId = `<h2${id}${attrs}>${content}</h2>`;
  const headingText = content.replace(/<[^>]*>/g, '').trim();

  let block = tagWithId;
  if (h2Count === 2 && img1) block += makeImgBlock(img1, headingText);
  if (h2Count === 5 && img2) block += makeImgBlock(img2, headingText);
  if (h2Count === 8 && img3) block += makeImgBlock(img3, headingText);
  if (h2Count === 11 && img4) block += makeImgBlock(img4, headingText);

  return block;
});

// Build Table of Contents
const allH2Tags = enhancedBody.match(/<h2[^>]*>[\s\S]*?<\/h2>/gi) || [];
if (allH2Tags.length > 0) {
  let tocItems = '';
  allH2Tags.forEach((tag, idx) => {
    const text = tag.replace(/<[^>]*>/g, '').trim();
    const id = tag.match(/id="([^"]+)"/)?.[1] || `section-${idx + 1}`;
    tocItems += `  <li><a href="#${id}" style="color:#c0392b;text-decoration:none;font-weight:500;">${text}</a></li>\n`;
  });

  const toc = `<div style="background:#fff8f5;border:2px solid #fde8e0;border-radius:12px;padding:24px 28px;margin:0 0 36px;">\n<p style="font-weight:700;font-size:17px;margin:0 0 14px;color:#c0392b;">\ud83d\udc68\u200d\ud83c\udf73 Jump to Section</p>\n<ol style="margin:0;padding-left:24px;line-height:2.2;">\n${tocItems}</ol>\n</div>\n`;

  return [{ json: { ...d, articleHTML: toc + enhancedBody, _imgInserted: (img1?1:0)+(img2?1:0)+(img3?1:0) } }];
}

return [{ json: { ...d, articleHTML: enhancedBody, _imgInserted: (img1?1:0)+(img2?1:0)+(img3?1:0) } }];

// Final validation and cleanup before posting
const createCleanSlug = (text) => {
  if (!text) return 'cooking-recipe';
  return text.toLowerCase()
    .replace(/[^a-z0-9\s-]/g, '')
    .replace(/\s+/g, '-')
    .replace(/-+/g, '-')
    .replace(/^-|-$/g, '')
    .substring(0, 60)
    .replace(/-$/, '');
};

const d = $json;
const validIds = [1,39,40,41,42,43,44,45,46,47];

const title = (d.title && d.title.length > 10) 
  ? d.title 
  : `${d.trendingTopic || 'Cooking'}: Complete Expert Guide`;

const slug = (d.slug && d.slug.length > 3) 
  ? createCleanSlug(d.slug) 
  : createCleanSlug(title);

const catId = validIds.includes(Number(d.category_id)) 
  ? Number(d.category_id) 
  : (validIds.includes(Number(d._forcedCategoryId)) ? Number(d._forcedCategoryId) : 1);

const tags = (d.tags && Array.isArray(d.tags) && d.tags.length >= 3) 
  ? d.tags 
  : ['recipes', 'cooking', 'food', 'homemade', 'kitchen tips', 'easy meals'];

const meta = (d.metaDescription && d.metaDescription.length > 30) 
  ? d.metaDescription 
  : `Master ${title.substring(0, 50)}: step-by-step expert guide with food science, tips, and recipes on texasdadcooks.com.`;

const excpt = (d.excerpt && d.excerpt.length > 20) 
  ? d.excerpt 
  : `Discover the ultimate guide to ${d.trendingTopic || 'cooking'} - professional techniques, food science, and pro tips from texasdadcooks.com.`;

const topicFirst = (d.trendingTopic || title).split(' ').slice(0, 4).join(' ');
const imgKw = [
  topicFirst + ' food recipe plated',
  topicFirst + ' fresh ingredients',
  'cooking kitchen chef action'
].map(k => k.substring(0, 100));

return [{ json: { ...d, title, slug, category_id: catId, tags, imageKeywords: imgKw, metaDescription: meta, excerpt: excpt } }];

// Select best featured image - MUST be different from inline images
const photos = $json.photos || [];
const artData = $('Validate & Finalize Article').first().json;

// Get IDs of images already used inline (from Enhance Article step)
// We cannot directly access usedImgIds from previous step, so we use a different page of results
// Pexels per_page=20 gives enough variety to pick a non-duplicate

// Pick photo with best relevance (first one that has good dimensions)
const goodPhotos = photos.filter(p => p.width >= 1200 && p.height >= 500);
const selected = goodPhotos.length > 0 ? goodPhotos[0] : (photos.length > 0 ? photos[0] : null);

if (!selected) {
  // No image found - use a generic cooking image search
  return [{ json: { ...artData, _imageUrl: null, _imageFallback: true } }];
}

const base = (selected.src?.original || selected.src?.large2x || '').split('?')[0];
const imgUrl = base + '?auto=compress&cs=tinysrgb&fit=crop&h=630&w=1200';

return [{ json: {
  ...artData,
  _imageUrl: imgUrl,
  _imageAlt: artData.title || 'Recipe',
  _imageId: selected.id,
  _photographerName: selected.photographer || 'Pexels',
  _photographerUrl: selected.photographer_url || 'https://www.pexels.com',
  _pexelsPageUrl: selected.url || 'https://www.pexels.com'
} }];

const mediaResp = $json;
const artData = $('Validate & Finalize Article').first().json;
const mediaId = mediaResp.id || 0;
const sourceUrl = mediaResp.source_url || '';
const pName = $('Build Featured Image URL').first().json._photographerName || 'Pexels';
const pUrl = $('Build Featured Image URL').first().json._photographerUrl || 'https://www.pexels.com';
const pgUrl = $('Build Featured Image URL').first().json._pexelsPageUrl || 'https://www.pexels.com';
const altText = (artData.title || 'Recipe').replace(/"/g, "'");

let finalHTML = artData.articleHTML || '';

if (mediaId && sourceUrl) {
  const imgBlock = `<figure class="wp-block-image size-large" style="margin-bottom:32px;">\n<img src="${sourceUrl}" alt="${altText}" style="width:100%;border-radius:10px;" width="1200" height="630"/>\n<figcaption style="font-size:11px;color:#888;text-align:center;margin-top:6px;font-style:italic;">Photo by <a href="${pUrl}" target="_blank" rel="noopener noreferrer">${pName}</a> on <a href="${pgUrl}" target="_blank" rel="noopener noreferrer">Pexels</a></figcaption>\n</figure>\n`;
  finalHTML = imgBlock + finalHTML;
}

// Update WP media alt text for SEO
if (mediaId) {
  try {
    await $http.post(
      `${$('Build Config').item.json._wpBase}/wp-json/wp/v2/media/${mediaId}`,
      { alt_text: altText, caption: `${altText} | texasdadcooks.com` },
      { headers: { 'Authorization': $('Build Config').item.json._auth, 'Content-Type': 'application/json' } }
    );
  } catch(e) { /* non-critical */ }
}

return [{ json: { ...artData, _mediaId: mediaId, articleHTML: finalHTML } }];

const artData = $input.first().json;
const tags = artData.tags || [];
const wpBase = $('Build Config').item.json._wpBase;
const auth = $('Build Config').item.json._auth;
const tagIds = [];

for (const tagName of tags) {
  const slug = tagName.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
  try {
    const searchRes = await $http.get(
      `${wpBase}/wp-json/wp/v2/tags?search=${encodeURIComponent(tagName)}&per_page=5`,
      { headers: { 'Authorization': auth } }
    );
    const existing = searchRes.data?.find(t => t.slug === slug || t.name.toLowerCase() === tagName.toLowerCase());
    if (existing) {
      tagIds.push(existing.id);
    } else {
      const createRes = await $http.post(
        `${wpBase}/wp-json/wp/v2/tags`,
        { name: tagName, slug },
        { headers: { 'Authorization': auth, 'Content-Type': 'application/json' } }
      );
      if (createRes.data?.id) tagIds.push(createRes.data.id);
    }
  } catch(e) { /* skip failed tags */ }
}

return [{ json: { ...artData, _tagIds: tagIds } }];

const artData = $input.first().json;

// Build Yoast SEO meta if available, else use standard fields
const postBody = {
  title: artData.title,
  content: artData.articleHTML,
  slug: artData.slug,
  status: 'publish',
  categories: [artData.category_id || 1],
  featured_media: artData._mediaId || 0,
  excerpt: artData.excerpt || '',
  tags: artData._tagIds || [],
  meta: {
    // Yoast SEO fields (works if Yoast plugin is installed)
    _yoast_wpseo_metadesc: artData.metaDescription || '',
    _yoast_wpseo_title: artData.title || ''
  }
};

return [{ json: { ...artData, _postBody: postBody } }];

// Log success for monitoring
const postResp = $json;
const artData = $('Prepare Post Body').first().json;

console.log(JSON.stringify({
  status: 'published',
  postId: postResp.id,
  postUrl: postResp.link,
  title: artData.title,
  category: artData.category_id,
  categoryName: artData._forcedCategoryName,
  topicSource: artData.topicSource,
  aiSource: artData._aiSource,
  imagesInserted: artData._imgInserted,
  timestamp: new Date().toISOString()
}));

return [{ json: {
  success: true,
  postId: postResp.id,
  postUrl: postResp.link,
  title: artData.title,
  category: artData._forcedCategoryName,
  topicSource: artData.topicSource,
  aiModel: artData._aiSource
} }];
